def stabilize(frames):
    """Remove sub-pixel camera shake so background edges do not flicker.

    Each frame is aligned to the median image by the global translation
    estimated with phase correlation, then the background is recomputed.
    """
    ref = background(frames).astype(np.float32)
    h, w = ref.shape
    try:
        window = cv2.createHanningWindow((w, h), cv2.CV_32F)
    except Exception:
        window = None
    aligned = []
    for frame in frames:
        cur = frame.astype(np.float32)
        try:
            if window is not None:
                shift, _ = cv2.phaseCorrelate(ref, cur, window)
            else:
                shift, _ = cv2.phaseCorrelate(ref, cur)
        except Exception:
            aligned.append(frame)
            continue
        dx, dy = float(shift[0]), float(shift[1])
        if abs(dx) < 0.05 and abs(dy) < 0.05:
            aligned.append(frame)
            continue
        mat = np.array([[1.0, 0.0, -dx], [0.0, 1.0, -dy]], dtype=np.float32)
        aligned.append(cv2.warpAffine(frame, mat, (w, h),
                                      flags=cv2.INTER_LINEAR,
                                      borderMode=cv2.BORDER_REPLICATE))
    return aligned, background(aligned)

